namespace sv_bc4c24a88ba947a3ab8b49a4360ebd30.Components;

public class CustomValidator : ComponentBase
{
    [CascadingParameter]
    private EditContext? EditContext { get; set; }

    private ValidationMessageStore? messageStore;

    protected override void OnInitialized()
    {
        messageStore = new ValidationMessageStore(EditContext!);
        EditContext!.OnValidationRequested += (s, e) => messageStore.Clear();
        EditContext!.OnFieldChanged += (s, e) => messageStore.Clear(e.FieldIdentifier);
    }

    public void DisplayErrors(Dictionary<string, List<string>> errors)
    {
        foreach (var (field, messages) in errors)
        {
            foreach (var message in messages)
            {
                messageStore!.Add(EditContext!.Field(field), message);
            }
        }
        EditContext!.NotifyValidationStateChanged();
    }

    public void ClearErrors()
    {
        messageStore?.Clear();
        EditContext?.NotifyValidationStateChanged();
    }
}

@page "/book-appointment"
@rendermode InteractiveServer
@using sv_bc4c24a88ba947a3ab8b49a4360ebd30.Services
@inject AppointmentService AppointmentService

<PageTitle>Book Appointment</PageTitle>

<h3>Book a Medical Appointment</h3>

@if (isSubmitted)
{
    <div class="alert alert-success mt-3">
        <strong>Appointment booked successfully!</strong>
        <p class="mb-0">
            @model.PatientName — @model.Doctor on @model.AppointmentDate?.ToString("MMM dd, yyyy") at @model.TimeSlot
        </p>
    </div>
}
else
{
    <EditForm EditContext="editContext" OnSubmit="HandleSubmit" FormName="book-appointment">
        <DataAnnotationsValidator />
        <CustomValidator @ref="customValidator" />

        @* ===== STEP 1 ===== *@
        <fieldset>
            <legend>Patient Information</legend>

            <div class="mb-3">
                <label class="form-label" for="patientName">Patient Name</label>
                <InputText id="patientName" class="form-control" @bind-Value="model.PatientName" />
                <ValidationMessage For="() => model.PatientName" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="email">Email</label>
                <InputText id="email" class="form-control" @bind-Value="model.Email" />
                <ValidationMessage For="() => model.Email" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="phone">Phone</label>
                <InputText id="phone" class="form-control" @bind-Value="model.Phone" />
                <ValidationMessage For="() => model.Phone" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="insurance">Insurance Provider</label>
                <InputSelect id="insurance" class="form-select" @bind-Value="model.InsuranceProvider">
                    <option value="">-- Select --</option>
                    <option value="Aetna">Aetna</option>
                    <option value="BlueCross">BlueCross</option>
                    <option value="Cigna">Cigna</option>
                    <option value="UnitedHealth">UnitedHealth</option>
                    <option value="None">None</option>
                </InputSelect>
                <ValidationMessage For="() => model.InsuranceProvider" />
            </div>

            @if (!showStepTwo)
            {
                <button type="button" class="btn btn-primary" @onclick="ProceedToStepTwo">
                    Next: Select Appointment
                </button>
            }
        </fieldset>

        @* ===== STEP 2 ===== *@
        @if (showStepTwo)
        {
            <fieldset class="mt-4">
                <legend>Appointment Details</legend>

                <div class="mb-3">
                    <label class="form-label" for="doctor">Preferred Doctor</label>
                    <InputSelect id="doctor" class="form-select" @bind-Value="model.Doctor"
                                 @bind-Value:after="OnDoctorOrDateChanged">
                        <option value="">-- Select --</option>
                        @foreach (var doc in doctors)
                        {
                            <option value="@doc">@doc</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => model.Doctor" />
                </div>

                <div class="mb-3">
                    <label class="form-label" for="date">Date</label>
                    <InputDate id="date" class="form-control" @bind-Value="model.AppointmentDate"
                               @bind-Value:after="OnDoctorOrDateChanged" />
                    <ValidationMessage For="() => model.AppointmentDate" />
                </div>

                <div class="mb-3">
                    <label class="form-label" for="timeSlot">Time Slot</label>
                    <InputSelect id="timeSlot" class="form-select" @bind-Value="model.TimeSlot">
                        <option value="">-- Select --</option>
                        @foreach (var slot in availableSlots)
                        {
                            <option value="@slot">@slot</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => model.TimeSlot" />
                </div>

                <div class="mb-3">
                    <label class="form-label" for="reason">Reason for Visit</label>
                    <InputTextArea id="reason" class="form-control" rows="3" @bind-Value="model.ReasonForVisit" />
                    <ValidationMessage For="() => model.ReasonForVisit" />
                </div>

                <button type="button" class="btn btn-secondary me-2" @onclick="BackToStepOne">Back</button>
                <button type="submit" class="btn btn-success" disabled="@isProcessing">
                    @(isProcessing ? "Checking Availability..." : "Check Availability & Book")
                </button>
            </fieldset>
        }
    </EditForm>
}

@code {
    private AppointmentModel model = new();
    private EditContext editContext = default!;
    private CustomValidator? customValidator;

    private bool showStepTwo;
    private bool isSubmitted;
    private bool isProcessing;

    private List<string> doctors = [];
    private List<string> availableSlots = [];

    // Tracks step-1 fields for partial validation
    private AppointmentStepOneModel stepOneModel = new();

    protected override async Task OnInitializedAsync()
    {
        editContext = new EditContext(model);
        doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void ProceedToStepTwo()
    {
        // Validate only step-1 fields by copying to a dedicated model
        stepOneModel.PatientName = model.PatientName;
        stepOneModel.Email = model.Email;
        stepOneModel.Phone = model.Phone;
        stepOneModel.InsuranceProvider = model.InsuranceProvider;

        var stepOneContext = new EditContext(stepOneModel);
        if (stepOneContext.Validate())
        {
            showStepTwo = true;
        }
        else
        {
            // Re-trigger validation on the main context so messages show
            editContext.Validate();
        }
    }

    private void BackToStepOne()
    {
        showStepTwo = false;
    }

    private async Task OnDoctorOrDateChanged()
    {
        if (!string.IsNullOrEmpty(model.Doctor) && model.AppointmentDate.HasValue)
        {
            availableSlots = await AppointmentService.GetAvailableTimeSlotsAsync(
                model.Doctor, model.AppointmentDate.Value);
            // Reset time slot if it's no longer in the list
            if (!availableSlots.Contains(model.TimeSlot ?? ""))
            {
                model.TimeSlot = null;
            }
        }
    }

    private async Task HandleSubmit()
    {
        customValidator?.ClearErrors();

        if (!editContext.Validate())
            return;

        // Future-date validation
        if (model.AppointmentDate.HasValue && model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
        {
            customValidator?.DisplayErrors(new Dictionary<string, List<string>>
            {
                [nameof(AppointmentModel.AppointmentDate)] = ["Appointment date must be in the future."]
            });
            return;
        }

        isProcessing = true;
        try
        {
            var errors = await AppointmentService.ValidatePatientAsync(
                model.Email!,
                model.InsuranceProvider!,
                model.Doctor,
                model.TimeSlot);

            if (errors.Count > 0)
            {
                customValidator?.DisplayErrors(errors);
                return;
            }

            isSubmitted = true;
        }
        finally
        {
            isProcessing = false;
        }
    }
}

